import java.util.*;class Solution {    public TreeSet<Integer> s = new TreeSet<>();    public int[] solution(String[] operations) {        StringTokenizer st;        int[] answer = new int[2];        for(int i = 0; i < operations.length; i++) {            st = new StringTokenizer(operations[i]);            String commend = st.nextToken();            int num = Integer.parseInt(st.nextToken());            if(commend.equals("I")) {                s.add(num);            }            if(commend.equals("D")) {                if(num == 1) {                    if(s.isEmpty()) continue;                    s.remove(s.last());                }                if(num == -1) {                    if(s.isEmpty()) continue;                    s.remove(s.first());                }            }        }        if(s.isEmpty()) {            answer[0] = 0;            answer[1] = 0;        }else {            answer[0] = s.last();            answer[1] = s.first();        }        return answer;    }}